create or replace TABLE LDL_DATA_PRODUCTION.EVAL.T_DISCOUNT_LINE_20250408_2 cluster by (
     COUNTRY_ORG_CD,
     BUS_DT
)(
	RETAIL_EVENT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related retail transaction, i.e. for the sales_2 or return of products..',
	RETAIL_EVENT_LINE_SEQ NUMBER(38,0) NOT NULL COMMENT 'The number of the line in the retail event. (Note that depending on the cash register software, this number is either a line number on the receipt or the sequence number of the discount which has been applied, so 1 for the first discount, 2 for the second discount and so on.)',
	DISCOUNTED_LINE_SEQ NUMBER(38,0) NOT NULL COMMENT 'The line to which the discount was applied.',
	EVENT_TMSP TIMESTAMP_TZ(9) NOT NULL COMMENT 'The point in time when the discount was appliled.',
	BUS_DT DATE NOT NULL COMMENT 'The business date on which the retail event is counted.',
	STORE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the store where the related retail event happend.',
	COUNTRY_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related country_2 organization.',
	COUNTRY_ORG_CD VARCHAR(2) NOT NULL COMMENT 'The code of the related business country. (The business country_2 is not identical to a political country.)',
	REAL_ESTATE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the real estate object.',
	CASH_REGISTER_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the cash register which has created this transaction.',
	CASH_REGISTER_TYPE_CD VARCHAR(20) COMMENT 'The code identifying the type of cash register. (standard cash register, self-checkout system, vending machine)',
	CASH_REGISTER_USG_TYPE_CD VARCHAR(20) COMMENT 'The code identifying the way, how a cash register is used. It distinguishes between regular operations, training and maintenance.',
	CASHIER_HASH VARCHAR(32) NOT NULL COMMENT 'The encrypted number of the cashier. (The hash is unique for a given store and a day.)',
	AUTH_BY_HASH VARCHAR(32) COMMENT 'In case of a cancellation or any other non-standard operation, the transaction must be authorized by the store manager or by another employee. This is the encrypted number which identifies the employee_2, who has authorized the transaction. (The hash is unique for a given store and a day.)',
	CUST_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for the customer.',
	RETAIL_EVENT_LINE_SCENARIO_ID NUMBER(38,0) NOT NULL COMMENT 'The numeric identifier for the scenario which is represented by the retail event line.',
	PROD_VARIANT_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for the product variant (sales_2 variant), for which the discount was given,',
	DISCOUNTED_CNT NUMBER(38,0) COMMENT 'The number of products to which the discount was applied - in case the product is sold by piece.',
	DISCOUNTED_QTY NUMBER(38,5) COMMENT 'The quanitity of the product to which the discount was applied - in case the product is sold by weight.',
	UOM_CD VARCHAR(20) COMMENT 'The code identifying the unit_2 of measure.',
	DISCOUNTED_VAL NUMBER(38,5) NOT NULL COMMENT 'The base amount to which the discount has been applied. (in the currency indicated by the currency code)',
	DISCOUNT_VAL NUMBER(38,5) NOT NULL COMMENT 'The (gross) amount of the discount. (in the currency indicated by the currency code)',
	CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency, according to ISO 4217.',
	DISCOUNT_PCT NUMBER(38,5) COMMENT 'The discount percentage which has been given.',
	DISCOUNT_NAME VARCHAR(100) COMMENT 'The name of the discount that is applied.',
	PROMO_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for a promotion.',
	DISCOUNT_TYPE_CD VARCHAR(20) COMMENT 'The code for kind of discount. It shows, if the price for the product was reduced, or if the product was free.',
	DISCOUNT_REASON_CD VARCHAR(20) COMMENT 'The code identifying the reason for a discount. A discount can be initiated by the cashier or triggered by a rule.',
	DISCOUNT_CALC_RULE_CD VARCHAR(20) COMMENT 'The code identifying the rule, how a discount is calculated.',
	CANCEL_LINE_SEQ NUMBER(38,0) COMMENT 'In case the related product retail line is cancelled, then the discount line is cancelled, as well. This is the number of the related cancellation line.',
	SPLIT_FG BOOLEAN COMMENT 'An indicator showing, if the discount was given on receipt level and subsequently split across multiple receipt lines.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_DISCOUNT_LINE primary key (RETAIL_EVENT_SID, RETAIL_EVENT_LINE_SEQ, DISCOUNTED_LINE_SEQ)
)COMMENT='A discount is a price reduction of an item_2 or a service. It may be given as a fix percent value, e.g. 10%, or it can be defined with more complex logic, e,g, 1 discount for a LidlPlus customer, buy 3 pay 2, etc.'
;